  const [mobDays,setMobDays]=useState(0);
  const [wbhDays,setWbhDays]=useState(0);
  const [smeDays,setSmeDays]=useState(1);
  const [step,setStep]=useState("supplier");
  const [animIn,setAnimIn]=useState(true);
