      ai_tray_vision_checkout:supplier==="VISION_CHECKOUT"?String(scanners):"0",
      deligo_ai_scanners:     supplier==="DELIGO"?String(scanners):"0",
      t2e_control_desk:       supplier==="DELIGO"?(t2eExisting===false?"1":"0"):"0",
